29391, 29392, 32000, 32272, 32245, 34300, 34400, 33740, 35303, 35268, 33000) -- -- AND op_id IN (33000) -- AND group_id > 0 -- AND s.os = 'Android' AND s.os = 'iOS' AND s.country = 'IND' -- GROUP BY 1,2,3,4,5,6,7,8,9 ), sl_deduped AS ( SELECT mri_session_id, route_id, user_origin, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-03-31 18:30:00' AND __time < TIMESTAMP '2026-04-06 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2,3 ), pay AS ( SELECT order_uuid, MAX(CASE WHEN payment_system IN ('OPOFFER', 'OP_SL_OFFER') THEN 1 ELSE 0 END) AS redDeal_Txn FROM "transaction"."bus_payment_events" WHERE date_of_issue >= TIMESTAMP '2026-03-31 18:30:00' AND date_of_issue < TIMESTAMP '2026-04-06 18:30:00' AND country_code = 'IND' GROUP BY 1 ), txn AS ( SELECT order_uuid, mri_session_id, route_id, tin FROM "transaction"."bus_ticket_events" WHERE date_of_issue >= TIMESTAMP '2026-03-31 18:30:00' AND date_of_issue < TIMESTAMP '2026-04-06 18:30:00' AND country_code = 'IND' AND event_class = 101 AND event_type = 2 GROUP BY 1,2,3,4 ), red_deal AS ( SELECT t.mri_session_id, t.route_id, t.tin, p.redDeal_Txn FROM txn t LEFT JOIN pay p ON t.order_uuid = p.order_uuid ) SELECT '01 to 06 April 2026' AS month_period, -- srp.doi, srp.exp_Variant, -- srp.iOS_Variant, UPPER(srp.user_type) as user_type, -- 'Overall' AS user_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, CASE WHEN redDeal_Txn = 1 THEN 'Yes' ELSE 'No' END AS redDeal_Txn, -- CASE WHEN srp.doj = srp.doi AND srp.day_hour < 10 THEN 'Same Day before 10 AM' -- WHEN srp.doj = srp.doi AND srp.day_hour >= 10 THEN 'Same Day after 10 AM' -- WHEN srp.doj > srp.doi AND srp.day_hour < 10 THEN 'Other Day' -- ELSE 'NA' END -- 'Any DBD' -- AS dbd, -- srp.route_type, -- srp.is_ac, -- 'Overall' AS is_ac, -- srp.op_id, -- bo.travels rtc, -- '' AS RTC_Cohort, -- CASE WHEN srp.os IS NOT NULL THEN srp.channel ELSE srp.os END AS saleschannel, COUN